ALTER TABLE pocketsound_users
ADD COLUMN is_banned BOOLEAN DEFAULT FALSE;

ALTER TABLE pocketsound_users
ADD COLUMN ban_reason TEXT;

ALTER TABLE pocketsound_users
ADD COLUMN banned_at TIMESTAMP;

ALTER TABLE pocketsound_users
ADD COLUMN support_topic_id BIGINT;

CREATE INDEX idx_pocketsound_users_topic
ON pocketsound_users(support_topic_id);

CREATE INDEX idx_credentials_login ON pocketsound_credentials(login);
CREATE INDEX idx_credentials_user_id ON pocketsound_credentials(user_id);
CREATE INDEX idx_auth_codes_user_id ON pocketsound_auth_codes(user_id);
CREATE INDEX idx_auth_codes_code ON pocketsound_auth_codes(code);
CREATE INDEX idx_auth_codes_expires ON pocketsound_auth_codes(expires_at);
CREATE INDEX idx_auth_codes_type ON pocketsound_auth_codes(code_type);
CREATE INDEX idx_sessions_user_id ON pocketsound_sessions(user_id);
CREATE INDEX idx_sessions_refresh_token ON pocketsound_sessions(refresh_token);
CREATE INDEX idx_sessions_expires ON pocketsound_sessions(expires_at);
CREATE INDEX idx_users_email ON pocketsound_users(email);

ALTER TABLE pocketsound_users
ADD COLUMN IF NOT EXISTS referrer_id BIGINT,
ADD COLUMN IF NOT EXISTS referral_link TEXT;

CREATE INDEX IF NOT EXISTS idx_pocketsound_users_referrer_id
ON pocketsound_users(referrer_id);

COMMENT ON COLUMN pocketsound_users.referrer_id IS 'User ID who invited this user';
COMMENT ON COLUMN pocketsound_users.referral_link IS 'User personal referral link to invite others';

ALTER TABLE pocketsound_users
ADD COLUMN admin_active BOOLEAN DEFAULT FALSE;

COMMENT ON COLUMN pocketsound_users.admin_active IS 'Admin mode active - user cannot use bot commands';
